import type { ConferenceDoc, PingDoc, UserDoc } from "./types";

export function serializeUser(id: string, d: UserDoc) {
  return {
    id,
    avatarId: d.avatar_id,
    email: d.email ?? null,
    displayName: d.display_name ?? null,
    photoURL: d.photo_url ?? null,
    isAdmin: !!d.is_admin,
    createdAt: d.created_at,
  };
}

export function serializeUserSummary(id: string, d: UserDoc) {
  return {
    id,
    avatarId: d.avatar_id,
    displayName: d.display_name ?? null,
    photoURL: d.photo_url ?? null,
  };
}

export function serializeConference(id: string, d: ConferenceDoc) {
  return {
    id,
    name: d.name,
    locationName: d.location_name,
    latitude: d.latitude,
    longitude: d.longitude,
    startDate: d.start_date,
    endDate: d.end_date,
    source: d.source,
    topics: d.topics ?? [],
    url: d.url ?? null,
    createdAt: d.created_at,
  };
}

export function pingIntensity(
  createdAt: string,
  now: number,
  decayDays: number
): number {
  const ageDays = (now - Date.parse(createdAt)) / 86_400_000;
  return Math.max(0, 1 - ageDays / decayDays);
}

export function serializePing(id: string, d: PingDoc, now: number, decayDays: number) {
  return {
    id,
    createdAt: d.created_at,
    intensity: pingIntensity(d.created_at, now, decayDays),
  };
}

export function decayDays(): number {
  const v = Number(process.env.PING_DECAY_DAYS);
  return Number.isFinite(v) && v > 0 ? v : 30;
}

export function decayCutoffISO(now = Date.now()): string {
  return new Date(now - decayDays() * 86_400_000).toISOString();
}

