  | "forbidden"
  | "not_found"
  | "conflict"
  | "rate_limited"
  | "internal";

export function httpError(
  status: 400 | 401 | 403 | 404 | 409 | 429 | 500,
  code: ErrorCode,
  message: string,
  extra?: { details?: unknown; headers?: Record<string, string> }
): HTTPException {
  const body: { error: { code: ErrorCode; message: string; details?: unknown } } = {
    error: { code, message },
  };
  if (extra?.details !== undefined) body.error.details = extra.details;
  const res = new Response(JSON.stringify(body), {
    status,
    headers: {
      "content-type": "application/json",
      ...(extra?.headers ?? {}),
    },
  });
  return new HTTPException(status, { res, message });
}

export const unauthenticated = (msg = "Authentication required.") =>
  httpError(401, "unauthenticated", msg);
export const forbidden = (msg = "Not permitted.") => httpError(403, "forbidden", msg);
export const notFound = (msg = "Not found.") => httpError(404, "not_found", msg);
export const conflict = (msg: string) => httpError(409, "conflict", msg);
export const rateLimited = (retryAfter: number, msg = "Rate limit exceeded.") =>
  httpError(429, "rate_limited", msg, { headers: { "Retry-After": String(retryAfter) } });

