        ({ data }) =>
          data.name.toLowerCase().includes(needle) ||
          data.location_name.toLowerCase().includes(needle)
      )
      .slice(0, 500)
      .map(({ id, data }) => serializeConference(id, data));
    return c.json({ conferences: filtered });
