// Shared setup for data pipeline scripts.
// Defaults to emulators; pass --production to target a real project.

import { initializeApp, getApps, cert, applicationDefault } from "firebase-admin/app";
import { getFirestore } from "firebase-admin/firestore";
import { getAuth } from "firebase-admin/auth";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const projectRoot = join(__dirname, "..", "..", "..");

export function parseArgs(argv) {
  const args = { flags: new Set(), opts: {} };
  for (let i = 2; i < argv.length; i++) {
    const a = argv[i];
    if (a.startsWith("--")) {
      const key = a.slice(2);
      const next = argv[i + 1];
      if (next && !next.startsWith("--")) {
        args.opts[key] = next;
        i++;
      } else {
        args.flags.add(key);
      }
    }
  }
  return args;
}

export function loadProjectId(isProduction) {
  if (!isProduction) return "demo-confgo";
  const rc = JSON.parse(readFileSync(join(projectRoot, ".firebaserc"), "utf-8"));
  return rc.projects?.default || "demo-confgo";
}

export function connectEmulatorsIfNeeded(isProduction) {
  if (isProduction) return;
  process.env.FIRESTORE_EMULATOR_HOST ||= "127.0.0.1:8080";
  process.env.FIREBASE_AUTH_EMULATOR_HOST ||= "127.0.0.1:9099";
  process.env.FIREBASE_STORAGE_EMULATOR_HOST ||= "127.0.0.1:9199";
}

export function initAdmin({ isProduction, projectId }) {
  if (getApps().length) return;
  connectEmulatorsIfNeeded(isProduction);
  if (isProduction) {
    initializeApp({ credential: applicationDefault(), projectId });
  } else {
    initializeApp({ projectId });
  }
}

export { getFirestore, getAuth, projectRoot };

