export interface User {
  id: string;
  avatarId: number;
  email: string | null;
  displayName: string | null;
  photoURL: string | null;
  isAdmin: boolean;
  createdAt: ISO8601;
}

export interface UserSummary {
  id: string;
  avatarId: number;
  displayName: string | null;
  photoURL: string | null;
}

export interface Conference {
  id: string;
  name: string;
  locationName: string;
  latitude: number;
  longitude: number;
  startDate: ISO8601;
  endDate: ISO8601;
  source?: string;
  topics?: string[];
  url?: string | null;
  createdAt: ISO8601;
}

export interface Attendance {
  conferenceId: string;
  intent: "been" | "going";
  createdAt: ISO8601;
}

