import { auth } from "../config/firebase";
import type {
  Attendance,
  Attendee,
  Conference,
  CoPeer,
  IncomingPing,
  MutualContact,
  OutgoingPing,
  User,
  UserSummary,
} from "./types";

const BASE = "/api";

async function authHeaders(): Promise<Record<string, string>> {
  const user = auth.currentUser;
  if (!user) return {};
  const token = await user.getIdToken();
  return { Authorization: `Bearer ${token}` };
}

interface ApiErrorBody {
  error: { code: string; message: string; details?: unknown };
}

export class ApiError extends Error {
  code: string;
  status: number;
  details?: unknown;
  retryAfter?: number;
  constructor(status: number, body: ApiErrorBody, retryAfter?: number) {
    super(body.error.message || `Request failed (${status})`);
    this.status = status;
    this.code = body.error.code;
    this.details = body.error.details;
    this.retryAfter = retryAfter;
  }
}

async function request<T>(path: string, init: RequestInit = {}): Promise<T> {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    ...(await authHeaders()),
    ...((init.headers as Record<string, string>) ?? {}),
  };
  const res = await fetch(`${BASE}${path}`, { ...init, headers });
  if (!res.ok) {
    let body: ApiErrorBody;
    try {
      body = await res.json();
    } catch {
      body = { error: { code: "internal", message: `HTTP ${res.status}` } };
    }
    const retry = Number(res.headers.get("Retry-After"));
    throw new ApiError(res.status, body, Number.isFinite(retry) ? retry : undefined);
  }
  if (res.status === 204) return undefined as T;
  return res.json();
}

// --- Me ---
export const getMe = () => request<User>("/me");
export const patchMe = (body: Partial<Pick<User, "avatarId" | "displayName" | "photoURL">>) =>
  request<User>("/me", { method: "PATCH", body: JSON.stringify(body) });
export const getMyAttendances = () =>
  request<{ attendances: Attendance[] }>("/me/attendances");
export const getCoAttendance = () => request<{ peers: CoPeer[] }>("/me/co-attendance");

// --- Conferences ---
export const listConferences = (q?: string) =>
  request<{ conferences: Conference[] }>(`/conferences${q ? `?q=${encodeURIComponent(q)}` : ""}`);
export const getConference = (id: string) => request<Conference>(`/conferences/${id}`);
export const createConference = (body: {
  name: string;
  locationName: string;
  latitude: number;
  longitude: number;
  startDate: string;
  endDate: string;
  topics?: string[];
  url?: string | null;
}) => request<Conference>("/conferences", { method: "POST", body: JSON.stringify(body) });
export const getConferenceAttendees = (id: string) =>
  request<{ attendees: Attendee[] }>(`/conferences/${id}/attendees`);
export const markAttendance = (id: string, intent: "been" | "going") =>
  request<{ ok: true }>(`/conferences/${id}/attend`, {
    method: "POST",
    body: JSON.stringify({ intent }),
  });
export const unmarkAttendance = (id: string) =>
  request<{ ok: true }>(`/conferences/${id}/attend`, { method: "DELETE" });

// --- Users ---
export const searchUsers = (q: string) =>
  request<{ users: UserSummary[] }>(`/users/search?q=${encodeURIComponent(q)}`);
export const getUserProfile = (userId: string) =>
  request<{ user: UserSummary; conferences: Conference[]; shared: Conference[] }>(
    `/users/${userId}/profile`
  );
export const getSharedMap = (peerId: string) =>
  request<{ conferences: Conference[] }>(`/users/${peerId}/shared-map`);
export const getSharedWithUsers = (userIds: string[]) =>
  request<{ conferences: Conference[] }>("/users/shared-conferences", {
    method: "POST",
    body: JSON.stringify({ userIds }),
  });
export const sendPing = (targetId: string) =>
  request<{ ok: true }>(`/users/${targetId}/ping`, { method: "POST" });

// --- Pings ---
export const getIncomingPings = () => request<{ incoming: IncomingPing[] }>("/pings/incoming");
export const getOutgoingPings = () => request<{ outgoing: OutgoingPing[] }>("/pings/outgoing");
export const pingBack = (pingId: string) =>
  request<{ ok: true }>(`/pings/${pingId}/ping-back`, { method: "POST" });
export const rejectPing = (pingId: string) =>
  request<{ ok: true }>(`/pings/${pingId}/reject`, { method: "POST" });
export const revokePing = (pingId: string) =>
  request<{ ok: true }>(`/pings/${pingId}/revoke`, { method: "POST" });
export const dematch = (peerId: string) =>
  request<{ ok: true }>(`/pings/dematch/${peerId}`, { method: "POST" });
export const getMutualContacts = () =>
  request<{ contacts: MutualContact[] }>("/pings/mutual-contacts");

