export const PING_DECAY_DAYS = 30;
export const CONF_HALF_LIFE_DAYS = 180;

export function conferenceGlow(startISO: string, endISO: string, now: number): number {
  const start = Date.parse(startISO);
  const end = Date.parse(endISO);
  if (now >= start && now <= end) return 1.0;
  const daysAway =
    now < start ? (start - now) / 86_400_000 : (now - end) / 86_400_000;
  const raw = Math.pow(2, -daysAway / CONF_HALF_LIFE_DAYS);
  return Math.max(0.08, raw);
}

export function pingIntensity(createdISO: string, now: number): number {
  const age = (now - Date.parse(createdISO)) / 86_400_000;
  return Math.max(0, 1 - age / PING_DECAY_DAYS);
}

export function isPast(endISO: string, now: number): boolean {
  return Date.parse(endISO) < now;
}

export function isFuture(startISO: string, now: number): boolean {
  return Date.parse(startISO) > now;
}

