export function formatDateRange(startISO: string, endISO: string): string {
  const start = new Date(startISO);
  const end = new Date(endISO);
  const sameDay = start.toDateString() === end.toDateString();
  const fmtDay = (d: Date) =>
    d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
  const fmtYear = (d: Date) => d.getFullYear();
  if (sameDay) return `${fmtDay(start)}, ${fmtYear(start)}`;
  if (start.getFullYear() === end.getFullYear()) {
    return `${fmtDay(start)} – ${fmtDay(end)}, ${fmtYear(start)}`;
  }
  return `${fmtDay(start)}, ${fmtYear(start)} – ${fmtDay(end)}, ${fmtYear(end)}`;
}

export function relativeLabel(startISO: string, endISO: string, now = Date.now()): string {
  const start = Date.parse(startISO);
  const end = Date.parse(endISO);
  if (now >= start && now <= end) return "now";
  if (now < start) {
    const d = Math.round((start - now) / 86_400_000);
    if (d === 0) return "today";
    if (d === 1) return "tomorrow";
    if (d < 30) return `in ${d} days`;
    if (d < 60) return "next month";
    return `in ${Math.round(d / 30)} mo`;
  }
  const d = Math.round((now - end) / 86_400_000);
  if (d === 1) return "yesterday";
  if (d < 30) return `${d} days ago`;
  if (d < 365) return `${Math.round(d / 30)} mo ago`;
  return `${Math.round(d / 365)} yr ago`;
}

