  const [count, setCount] = useState(0);

  useEffect(() => {
    if (!userId) {
      setCount(0);
      return;
    }
    const q = query(
      collection(firestore, "pings"),
      where("to_user_id", "==", userId),
      where("rejected_at", "==", null)
    );
