      const cutoff = Date.now() - PING_DECAY_DAYS * 86_400_000;
      let live = 0;
      snap.forEach((doc) => {
        const d = doc.data() as { created_at: string };
        if (Date.parse(d.created_at) >= cutoff) live++;
      });
      setCount(live);
    });
    return unsub;
  }, [userId]);

  return count;
}

