import { useState } from "react";
import { AvatarGlyph } from "./AvatarGlyph";
import type { PingIndicator } from "../lib/types";

interface Props {
  avatarId: number;
  photoURL: string | null;
  displayName: string | null;
  size?: number;
  pingIndicator?: PingIndicator;
}

export function UserAvatar({
  avatarId,
  photoURL,
  displayName,
  size = 40,
  pingIndicator = null,
}: Props) {
  const [photoFailed, setPhotoFailed] = useState(false);
  const label = displayName || "Unnamed";
  const showPhoto = photoURL && !photoFailed;

  return (
    <span
      className="avatar-glyph"
      style={{
        width: size,
        height: size,
        fontSize: size * 0.5,
        background: showPhoto
          ? undefined
          : undefined /* fall-through handled inside AvatarGlyph */,
      }}
      role="img"
      aria-label={label}
    >
      {showPhoto ? (
        <img
          src={photoURL!}
          alt=""
          onError={() => setPhotoFailed(true)}
          draggable={false}
        />
      ) : (
        <AvatarGlyph avatarId={avatarId} size={size} title={label} />
      )}
      {pingIndicator && <span className={`ping-ring ${pingIndicator}`} aria-hidden="true" />}
    </span>
  );
}

