import { useCallback, useEffect, useState } from "react";
import {
  dematch,
  getIncomingPings,
  getMutualContacts,
  getOutgoingPings,
  pingBack,
  rejectPing,
  revokePing,
} from "../lib/api";
import type { IncomingPing, MutualContact, OutgoingPing } from "../lib/types";
import { UserAvatar } from "./UserAvatar";
